@Component("creativeAsset-handler")
@ProcessingGroup("creativeAsset-processing-group")
public class CreativeAssetEventHandler {
	
	// core constructor
	CreativeAssetEventHandler(EntityManager entityManager) {
        this.entityManager = entityManager;
    }	
	
    /*
     * @param	event CreateCreativeAssetEvent
     */
    @EventHandler
    public void handle( CreateCreativeAssetEvent event) {
        entityManager.persist(new CreativeAsset(event.getCreativeAssetId(), event.getName(), event.getClickUrl(), event.getLandingPage(), event.getWidth(), event.getHeight(), event.getDurationSeconds(), event.getFiles(), event.getApprovals(), event.getVariations(), event.getLineItems(), event.getCreativeType(), event.getAdFormat()));
    }

    /*
     * @param	event UpdateCreativeAssetEvent
     */
    @EventHandler
    public CreativeAsset handle( UpdateCreativeAssetEvent event) {
    	entityManager.merge(new CreativeAsset(event.getCreativeAssetId(), event.getName(), event.getClickUrl(), event.getLandingPage(), event.getWidth(), event.getHeight(), event.getDurationSeconds(), event.getFiles(), event.getApprovals(), event.getVariations(), event.getLineItems(), event.getCreativeType(), event.getAdFormat()));
    }
    
    /*
     * @param	event DeleteCreativeAssetEvent
     */
    @EventHandler
    public void on( DeleteCreativeAssetEvent event) {
    	CreativeAsset entity = new CreativeAsset();
   
    	// ------------------------------------------
    	// apply the CreativeAssetId
    	// ------------------------------------------
    	entity.setCreativeAssetId( event.getCreativeAssetId() );
    	
    	// ------------------------------------------
    	// add to an Iterable and delete
    	// ------------------------------------------
    	entityManager.remove( entity );
    }    
    
    // attributes
	private final CreativeAssetRepository creativeAssetEntityRepository;
    private static final Logger LOGGER 			= Logger.getLogger(CreativeAssetEventHandler.class.getName());

}
